SELECT ,
FROM bidding_supplier bs INNER JOIN supplier s on s.id = bs.supplier_id INNER JOIN supplier_detail d on d.supplier_id = bs.supplier_id
and bs.UUID = #{uuid} and bs.is_block = #{black}
AND bs.name like concat('%',#{name},'%')
AND bs.social_credit_code like concat('%',#{code},'%')
and bs.supplier_id in ( select detail_id from supplier_detail_subject_link where bool_delete_enum = 0 and subject_id in
#{item}
)
and bs.supplier_id in ( select detail_id from supplier_detail_region_link where bool_delete_enum = 0 and region_id in
#{item}
)
ORDER BY bs.create_time desc

select
s.id AS supplierId,

from supplier s
inner join supplier_detail d on d.supplier_id = s.id

    and s.bool_delete_enum = 0 and s.cert_status = 2 AND s.id NOT IN (select bs.supplier_id from bidding_supplier bs where bs.uuid = #{uuid})
    
        and s.name like CONCAT('%',#{name},'%')
    
    
        and d.social_credit_code like CONCAT('%',#{socialCreditCode},'%')
    
    
        and d.id in (
        select detail_id from supplier_detail_region_link where bool_delete_enum = 0 and region_id in
        
            #{item}
        
        )
    
    
        and d.id in (
        select detail_id from supplier_detail_subject_link where bool_delete_enum = 0 and subject_id in
        
            #{item}
        
        )
    
    
        and s.bool_enable_enum = #{boolEnableEnum}
